('use_of_english_0319', 'Use of English', 'Vowels', 'Vowel Sounds', NULL, '[{"weight": 1, "conceptId": "namskj"}]'::jsonb, '{}', 2, 'application', 60, 'low', 'none', '[{"option": "A", "explanation": "''Gourd'' has a different vowel sound (/ʊə/ or /ɔː/), not /ɑː/.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "''Guide'' has the diphthong /aɪ/, a different sound.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "''Chat'' has the short /æ/ sound, not the long /ɑː/ in ''guard''.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2005, 'JAMB', '{}', 'Choose the option that has the same vowel sound as the one represented by the letter(s) underlined.

